"""Article-specific editorial source for CC-08 (Civil Code arts. 401-460)."""
from __future__ import annotations


def row(says, means, example, warning, term, definition, *, target=None, terms=None):
    return {"target": target, "o_que_diz": says, "o_que_significa": means, "exemplo_pratico": example, "atencao": warning, "palavras_dificeis": terms or [{"termo": term, "explicacao": definition}]}


ROWS = {
    "401": row("A mora pode ser eliminada por iniciativa do devedor ou do credor. O devedor oferece a prestação e repara os prejuízos produzidos até a oferta; o credor se dispõe a receber e suporta os efeitos de seu atraso até essa data.", "Purgar a mora corrige o atraso e faz cessar seus efeitos futuros, mas não apaga danos já causados. A providência adequada depende de quem estava em mora.", "Devedor entrega a mercadoria atrasada e paga o custo adicional que o atraso gerou ao comprador.", "A oferta deve ser completa e ainda útil ao credor. Se o atraso tornou a prestação inútil, pode haver resolução e indenização em vez de purgação.", "Purgação da mora", "regularização do atraso com cumprimento e reparação dos efeitos já produzidos"),
    "402": row("A indenização compreende tanto o prejuízo patrimonial efetivamente sofrido quanto o ganho razoável que a vítima deixou de obter, salvo exceção legal.", "A reparação procura recompor a situação econômica provável sem o inadimplemento. Dano emergente é a perda concreta; lucro cessante é a receita provável frustrada, não mera expectativa remota.", "Máquina não entregue gera gasto com aluguel substitutivo e perda comprovável da produção esperada.", "O credor deve demonstrar dano e nexo causal. A palavra razoavelmente impede indenização baseada em lucro imaginário ou especulativo.", "Lucros cessantes", "ganhos prováveis que deixaram de ocorrer em razão direta do inadimplemento"),
    "403": row("Mesmo quando o devedor age dolosamente, a reparação contratual alcança os danos efetivos e lucros cessantes que sejam consequência direta e imediata da inexecução, preservadas as regras processuais.", "A norma limita a cadeia causal indenizável. A gravidade da conduta não transforma prejuízos indiretos, remotos ou desconectados em perdas reparáveis.", "Fornecedor rompe deliberadamente contrato; indeniza a compra substitutiva e a margem diretamente perdida, mas não todo impacto econômico distante alegado pelo cliente.", "Dolo pode influenciar outras consequências, porém não dispensa prova do dano nem do vínculo causal exigido neste artigo.", "Efeito direto e imediato", "prejuízo ligado à inexecução por relação causal suficientemente próxima"),
    "404": row("Nas dívidas em dinheiro inadimplidas, as perdas e danos incluem atualização monetária, juros, custas e honorários advocatícios, sem afastar cláusula penal aplicável. Se os juros moratórios forem insuficientes e não houver pena convencional, o juiz pode conceder reparação adicional mediante prova.", "A atualização recompõe o valor da moeda; juros remuneram o atraso; despesas processuais e advocatícias integram as consequências previstas. A indenização suplementar não é automática.", "Atraso em dívida monetária causa perda comprovada superior aos juros; sem cláusula penal, o credor pede complemento ao juiz.", "A redação da Lei 14.905/2024 não autoriza duplicidade pelo mesmo prejuízo. O complemento exige insuficiência provada e ausência de pena convencional.", "Indenização suplementar", "reparação adicional concedida quando os encargos comuns não cobrem o dano demonstrado"),
    "405": row("Como regra deste artigo, os juros de mora são contados a partir da citação inicial.", "A citação marca o termo inicial dos juros nas hipóteses em que não exista marco anterior decorrente da lei, do contrato ou da própria natureza da obrigação.", "Devedor citado em ação de cobrança passa a sofrer juros moratórios desde esse ato, quando nenhuma regra fixa data anterior.", "O dispositivo deve ser coordenado com as regras de mora automática, ato ilícito e vencimento. Não significa que toda obrigação só gere juros depois da citação.", "Citação inicial", "ato processual que chama o réu para integrar a relação judicial"),
    "406": row("Na falta de taxa convencionada, quando o contrato menciona juros sem indicar percentual ou quando a própria lei os impõe, aplica-se a taxa legal. Ela corresponde à Selic descontada da atualização monetária subsidiária do art. 389; a metodologia cabe ao Conselho Monetário Nacional e a divulgação ao Banco Central. Resultado negativo vira zero no período.", "A Lei 14.905/2024 separa atualização e juros para evitar dupla contagem. O cálculo oficial da taxa legal deve seguir a metodologia regulamentada, não simples escolha privada.", "Contrato prevê juros, mas não informa taxa; utiliza-se a taxa legal calculada e divulgada conforme as regras oficiais.", "A Selic não é aplicada de modo bruto neste artigo. Deve ser deduzido o índice indicado e respeitado o piso zero por período de referência.", "Taxa legal", "taxa de juros aplicável nas hipóteses definidas em lei ou quando falta percentual válido"),
    "407": row("Os juros moratórios são devidos mesmo sem prova específica de prejuízo. Alcançam dívidas em dinheiro e prestações de outra natureza depois que seu valor monetário for definido por sentença, arbitramento ou acordo.", "O atraso gera juros como consequência própria da mora. Para obrigação originalmente não pecuniária, é necessário convertê-la em quantia determinada antes de calcular o encargo.", "Prestação de entregar bem é convertida em valor por acordo; sobre essa quantia incidem juros de mora.", "A dispensa de provar prejuízo não elimina a necessidade de mora, valor definido e termo inicial juridicamente correto.", "Arbitramento", "fixação fundamentada do valor devido quando ele não estava previamente determinado"),
    "408": row("A cláusula penal incide quando o devedor, com culpa, deixa de cumprir a obrigação ou entra em mora.", "A pena convencional antecipa a consequência do inadimplemento, mas depende do fato previsto e de imputabilidade ao devedor. A incidência é de pleno direito quando esses requisitos se verificam.", "Empresa atrasa culposamente a entrega e deve a multa contratual prevista para mora.", "Não basta qualquer descumprimento formal: deve haver correspondência entre a infração e a cláusula, além de culpa quando exigida pelo artigo.", "Cláusula penal", "valor ou prestação previamente fixada para o caso de inadimplemento ou atraso"),
    "409": row("A cláusula penal pode ser pactuada junto com a obrigação ou depois dela e abranger inadimplemento total, violação de cláusula específica ou simples mora.", "As partes podem definir com precisão qual comportamento ativa a pena. A espécie escolhida influencia se a multa substitui ou pode acompanhar o cumprimento principal.", "Após assinar contrato, as partes acrescentam multa exclusiva para atraso na entrega mensal.", "A redação deve identificar a hipótese de incidência. Pena por inadimplemento total não recebe automaticamente o tratamento da pena moratória.", "Pena moratória", "cláusula penal destinada a sancionar atraso sem substituir a prestação principal"),
    "410": row("Quando a pena é prevista para inadimplemento total, ela se torna alternativa em favor do credor.", "Diante da inexecução completa, o credor escolhe a consequência compatível com a cláusula, em vez de cumular automaticamente a pena compensatória com a prestação integral.", "Vendedor não entrega definitivamente o bem; o comprador opta pela pena compensatória prevista para inexecução total.", "A alternativa pertence ao credor, mas não permite enriquecimento duplicado. Cumulação depende da natureza da pena e das regras aplicáveis.", "Pena compensatória", "multa ligada à inexecução total e destinada a substituir a prestação inadimplida"),
    "411": row("Se a pena foi estipulada para mora ou para proteger cláusula específica, o credor pode exigir simultaneamente a multa e o cumprimento da obrigação principal.", "A pena moratória não substitui a prestação: sanciona atraso ou infração particular enquanto preserva o interesse no cumprimento.", "Locatário paga tarde; o locador cobra o aluguel e a multa de mora.", "A cumulação não afasta controle de excessividade nem autoriza cobrar duas penalidades pelo mesmo fato sem base contratual.", "Cominação", "consequência patrimonial previamente fixada para determinada infração"),
    "412": row("A multa estabelecida em cláusula penal não pode superar o valor da obrigação principal.", "A lei impõe teto objetivo para impedir que a sanção contratual ultrapasse a própria prestação garantida.", "Obrigação principal vale dez mil reais; a pena convencional não pode ser fixada acima desse montante.", "O teto não impede redução adicional por cumprimento parcial ou excesso manifesto, conforme o artigo seguinte.", "Obrigação principal", "prestação central cujo cumprimento a cláusula penal procura assegurar"),
    "413": row("O juiz deve reduzir equitativamente a cláusula penal quando a obrigação tiver sido cumprida em parte ou quando a multa for manifestamente excessiva diante da natureza e da finalidade do negócio.", "A redução é instrumento de equilíbrio e considera tanto o aproveitamento parcial recebido quanto a desproporção concreta da sanção.", "Contrato foi cumprido em noventa por cento; o juiz reduz multa prevista sobre o valor integral.", "A redução não depende apenas de comparar números. Finalidade, gravidade, utilidade do cumprimento e contexto do negócio são relevantes.", "Redução equitativa", "diminuição judicial proporcional e adequada às circunstâncias do caso"),
    "414": row("Em obrigação indivisível, a falta de um devedor faz incidir a pena sobre todos, mas o valor integral só pode ser cobrado do culpado; os demais respondem apenas por suas quotas. Quem não teve culpa pode regressar contra o causador.", "A indivisibilidade comunica a incidência externa da pena, porém preserva a distribuição interna segundo culpa e participação.", "Um integrante impede entrega de obra única; o credor cobra dele toda a pena, enquanto os outros limitam-se às respectivas partes.", "Não confunda indivisibilidade com solidariedade. A cobrança integral contra o culpado decorre desta regra específica.", "Ação regressiva", "cobrança interna contra quem deve suportar definitivamente o valor pago"),
    "415": row("Se a obrigação for divisível, apenas o devedor ou herdeiro que infringir sua parte incorre na pena, proporcionalmente à parcela devida.", "Como cada fração pode ser cumprida separadamente, a sanção não se comunica a quem executou corretamente sua quota.", "Entre três entregas autônomas, só o responsável pela parcela atrasada paga multa correspondente a ela.", "É necessário confirmar que a prestação é realmente divisível e identificar a fração de cada obrigado.", "Obrigação divisível", "prestação que pode ser fracionada sem perder natureza, valor ou finalidade"),
    "416": row("O credor cobra a pena convencional sem precisar demonstrar prejuízo. Indenização acima da pena só é possível se o contrato a autorizou; nesse caso, a multa funciona como mínimo e o dano excedente deve ser provado.", "A cláusula penal liquida previamente um patamar de reparação. A cumulação adicional depende de previsão expressa e prova concreta do excedente.", "Contrato permite indenização complementar; o credor recebe a multa e comprova prejuízo superior para cobrar a diferença.", "Sem convenção de complemento, dano maior não autoriza ultrapassar a pena por esta regra. Continuam aplicáveis os controles de validade e redução.", "Pena convencional", "sanção contratual previamente quantificada pelas partes"),
    "417": row("Dinheiro ou bem móvel entregue como arras na conclusão do contrato deve ser devolvido ou abatido da prestação quando o negócio é cumprido, se tiver o mesmo gênero da prestação principal.", "As arras confirmam o contrato e antecipam parte econômica do ajuste. No cumprimento, não se transformam em ganho extra de quem as recebeu.", "Comprador entrega sinal em dinheiro, depois abatido do preço final do imóvel.", "A função das arras depende do contrato. Se houver direito de arrependimento, aplica-se o regime indenizatório do art. 420.", "Arras", "sinal entregue na formação do contrato para confirmá-lo ou disciplinar arrependimento"),
    "418": row("No inadimplemento, se falha quem entregou as arras, a outra parte pode desfazer o contrato e retê-las. Se falha quem as recebeu, quem deu o sinal pode desfazer o negócio e exigir devolução mais valor equivalente, com atualização, juros e honorários.", "A regra distribui consequência conforme o responsável pela inexecução e foi atualizada pela Lei 14.905/2024. Para quem recebeu o sinal, devolver mais o equivalente produz efeito econômico de restituição em dobro.", "Vendedor recebeu sinal e descumpre o contrato; comprador pede a resolução, a devolução e outro valor igual, com encargos.", "A incidência exige inexecução imputável. Indenização suplementar ou cumprimento seguem o art. 419; arras de arrependimento seguem o art. 420.", "Sinal confirmatório", "arras que confirmam o contrato e disciplinam consequências do inadimplemento"),
    "419": row("A parte inocente pode provar prejuízo maior e pedir indenização adicional, usando as arras como mínimo. Também pode exigir o cumprimento do contrato com perdas e danos, novamente com as arras como piso reparatório.", "O credor não fica limitado ao sinal quando demonstra dano superior e pode preferir tutela de cumprimento à resolução.", "Comprador prova que a quebra causou prejuízo acima do sinal e cobra a diferença.", "O excedente precisa ser comprovado e não pode duplicar a mesma perda. A escolha deve ser compatível com a utilidade e possibilidade do cumprimento.", "Taxa mínima", "patamar indenizatório assegurado sem impedir prova de dano superior"),
    "420": row("Se o contrato concede direito de arrependimento, as arras têm função exclusivamente indenizatória: quem as deu e desiste perde o sinal; quem as recebeu e desiste devolve o sinal mais outro valor equivalente. Não cabe indenização adicional.", "As arras penitenciais representam o preço previamente definido para exercer o arrependimento permitido, e não sanção por inadimplemento comum.", "Comprador desiste dentro da faculdade contratual e perde o sinal, sem pagar outra indenização.", "É indispensável que o direito de arrependimento esteja estipulado. Sem essa faculdade, aplicam-se as arras confirmatórias dos artigos anteriores.", "Arras penitenciais", "sinal ligado ao direito contratual de desistir mediante consequência econômica predeterminada"),
    "421": row("A liberdade de contratar deve respeitar a função social do contrato. Nas relações privadas, a intervenção externa deve ser mínima e a revisão contratual, excepcional.", "A autonomia das partes é regra, mas não opera isolada dos efeitos sociais e dos limites jurídicos do negócio. Ao mesmo tempo, o Código protege estabilidade e previsibilidade contratual.", "Empresas definem livremente riscos do fornecimento, desde que o ajuste não viole limites legais e sociais.", "Função social não autoriza revisão automática nem intervenção sem fundamento concreto. Leis especiais podem impor regime mais protetivo.", "Função social do contrato", "limite que relaciona a autonomia contratual a interesses e efeitos juridicamente relevantes além das partes"),
    "421-A": row("Contratos civis e empresariais são presumidos paritários e simétricos, salvo elementos concretos ou regime especial em sentido contrário. As partes podem fixar parâmetros interpretativos e de revisão, a alocação de riscos deve ser respeitada e a revisão deve ser excepcional e limitada.", "A norma reforça autonomia e previsibilidade, mas estabelece presunção superável. Desigualdade demonstrada ou legislação especial pode afastar o regime comum.", "Duas sociedades negociam matriz detalhada de riscos; em princípio, essa distribuição orienta eventual disputa.", "Paridade não é verdade absoluta. Vulnerabilidade concreta, vício, abuso e normas especiais continuam juridicamente relevantes.", "Contrato paritário", "ajuste em que as partes se encontram em condições negociais comparáveis, salvo prova contrária"),
    "422": row("As partes devem agir com probidade e boa-fé tanto ao concluir quanto ao executar o contrato.", "Boa-fé objetiva exige comportamento leal, cooperativo e coerente, além do simples cumprimento literal. Ela orienta deveres de informação, proteção e confiança na relação contratual.", "Fornecedor informa prontamente risco relevante descoberto durante a execução, evitando dano ao cliente.", "Boa-fé objetiva avalia condutas, não apenas intenção íntima. Seu conteúdo depende do contrato e das circunstâncias comprovadas.", "Boa-fé objetiva", "padrão jurídico de lealdade, cooperação e proteção da confiança"),
    "423": row("Em contrato de adesão, cláusula ambígua ou contraditória deve ser interpretada de modo mais favorável ao aderente.", "Quem redige unilateralmente o instrumento suporta o risco da falta de clareza. A regra equilibra a posição de quem apenas aceita condições predispostas.", "Plano padronizado contém duas regras incompatíveis sobre cobertura; prevalece a leitura favorável ao aderente.", "A norma exige verdadeira ambiguidade ou contradição e não permite reescrever cláusula clara sem outro fundamento jurídico.", "Aderente", "parte que aceita condições contratuais previamente elaboradas pela outra"),
    "424": row("É nula, no contrato de adesão, a cláusula pela qual o aderente renuncia antecipadamente a direito inerente à natureza do negócio.", "O predisponente não pode retirar, antes mesmo da execução, proteção essencial que caracteriza a relação contratual.", "Contrato padronizado de depósito não pode excluir antecipadamente todo direito do depositante à guarda do bem.", "A nulidade recai sobre a cláusula proibida. É preciso identificar se o direito realmente decorre da natureza do contrato.", "Renúncia antecipada", "abandono prévio de direito antes de surgir a situação concreta para exercê-lo"),
    "425": row("As partes podem criar contratos não tipificados especificamente na lei, desde que respeitem as normas gerais do Código.", "A autonomia privada permite combinar prestações e estruturar negócios novos. A ausência de tipo legal próprio não elimina requisitos de validade, boa-fé e demais limites obrigatórios.", "Empresas celebram contrato híbrido de tecnologia com licença, suporte e remuneração por desempenho.", "Contrato atípico não é contrato sem regras. Podem incidir normas gerais e, por analogia adequada, aspectos de tipos próximos.", "Contrato atípico", "negócio sem disciplina legal específica completa, construído pela autonomia das partes"),
    "426": row("Não é permitido contratar sobre herança de pessoa que ainda está viva.", "A sucessão futura não pode ser negociada antecipadamente como objeto contratual. A proibição protege liberdade, dignidade e regime sucessório.", "Filho não pode vender hoje a quota que espera herdar de pai vivo.", "A vedação não se confunde com negócios atuais do próprio titular sobre seus bens nem com planejamento sucessório realizado pelos instrumentos legalmente admitidos.", "Pacto sucessório", "contrato sobre herança de pessoa viva, vedado por esta regra"),
    "427": row("A proposta contratual vincula o proponente, salvo se seus termos, a natureza do negócio ou as circunstâncias mostrarem o contrário.", "Oferta suficientemente definida gera dever de mantê-la pelo período aplicável. A própria proposta pode reservar revogabilidade ou o contexto pode afastar vinculação.", "Fornecedor envia proposta firme com objeto, preço e prazo e deve mantê-la durante a validade indicada.", "Convite para negociar não é necessariamente proposta. É preciso verificar conteúdo essencial e intenção de vinculação.", "Proponente", "pessoa que apresenta oferta destinada à formação de contrato"),
    "428": row("A proposta perde obrigatoriedade quando não é aceita imediatamente por pessoa presente sem prazo, quando transcorre tempo suficiente para resposta de ausente, quando a resposta não é expedida no prazo ou quando a retratação chega antes ou junto da oferta.", "A duração da oferta varia conforme presença, prazo e meio de comunicação. Telefone e comunicação semelhante equivalem à contratação entre presentes.", "Oferta telefônica sem prazo não é aceita durante a conversa e deixa de vincular o proponente.", "Para ausentes, o texto distingue expedição da resposta e chegada da retratação. O meio e as circunstâncias determinam o tempo razoável.", "Pessoa ausente", "destinatário que não se comunica em interação imediata com o proponente"),
    "429": row("Oferta ao público vale como proposta se contiver os elementos essenciais do contrato, salvo indicação contrária das circunstâncias ou dos usos. Pode ser revogada pelo mesmo meio de divulgação quando essa faculdade foi ressalvada na própria oferta.", "Anúncio completo pode vincular como proposta, mas publicidade genérica pode ser apenas convite. A revogação exige reserva prévia e divulgação equivalente.", "Loja publica oferta completa e informa que pode revogá-la; eventual retirada é anunciada pelo mesmo canal.", "Leis especiais, inclusive regras de consumo, podem impor disciplina adicional. Não presuma revogabilidade sem ressalva.", "Oferta ao público", "proposta dirigida a destinatários indeterminados, mas com conteúdo contratual essencial"),
    "430": row("Se evento imprevisto fizer a aceitação chegar tarde, o proponente deve avisar imediatamente o aceitante; se não o fizer, responde pelos prejuízos causados.", "A comunicação evita que o aceitante permaneça acreditando que o contrato se formou. O dever surge quando o atraso não era previsível para ele.", "Resposta tempestivamente enviada atrasa por falha excepcional; o proponente percebe e informa de imediato que não aceita a chegada tardia.", "Silêncio não forma necessariamente o contrato, mas pode gerar responsabilidade pelos danos decorrentes da omissão de avisar.", "Aceitação tardia", "resposta que chega depois do momento útil para formar o contrato"),
    "431": row("Aceitação enviada depois do prazo ou acompanhada de adições, restrições ou alterações vale como nova proposta.", "Resposta que modifica a oferta não conclui o contrato original. Ela inverte os papéis: o antigo aceitante passa a proponente das novas condições.", "Comprador aceita preço, mas exige prazo diferente; o vendedor decide se aceita essa contraproposta.", "Mudança precisa ter conteúdo negocial. Esclarecimento que não altera a oferta pode receber tratamento diferente conforme o contexto.", "Contraproposta", "resposta modificativa que rejeita a oferta original e apresenta nova proposta"),
    "432": row("Quando os usos dispensam aceitação expressa ou o proponente a dispensou, o contrato se considera concluído se a recusa não chegar a tempo.", "Em certas relações, o silêncio acompanhado do contexto previsto pode valer como aceitação. A regra depende de costume negocial ou autorização clara do ofertante.", "Fornecedor habitual envia pedido nos termos usuais e dispensa confirmação; sem recusa tempestiva, o ajuste se forma.", "Silêncio isolado não equivale normalmente a consentimento. Devem existir as circunstâncias específicas descritas no artigo.", "Aceitação tácita", "concordância revelada por comportamento ou silêncio juridicamente qualificado"),
    "433": row("A aceitação é considerada inexistente quando a retratação do aceitante chega ao proponente antes dela ou ao mesmo tempo.", "O aceitante pode neutralizar sua resposta se a retirada for conhecida em momento anterior ou simultâneo, impedindo a formação do contrato.", "Aceitante envia concordância por carta e retratação por mensagem que chega primeiro; o contrato não se forma pela carta.", "Importa o momento de chegada ao proponente, não apenas a data em que cada comunicação foi enviada.", "Retratação", "comunicação que retira manifestação de vontade antes que ela produza o efeito contratual"),
    "434": row("Entre ausentes, em regra o contrato se aperfeiçoa quando a aceitação é expedida. A regra não vale se houve retratação eficaz, se o proponente prometeu aguardar a resposta ou se ela não chega no prazo convencionado.", "O Código adota expedição como momento geral, mas preserva situações em que a chegada da resposta é decisiva.", "Aceitação é enviada dentro do prazo e forma o contrato, salvo cláusula que exija seu recebimento tempestivo.", "A identificação do momento pode afetar riscos e lei aplicável. Verifique também o meio utilizado e as exceções expressas.", "Teoria da expedição", "regra que considera formado o contrato quando a aceitação é enviada"),
    "435": row("O contrato é considerado celebrado no local onde a proposta foi feita.", "A regra fixa juridicamente o lugar da formação, útil para questões de competência, interpretação e conexão territorial.", "Empresa em Recife envia proposta aceita por destinatário em Salvador; o lugar contratual, por esta regra, é Recife.", "Contratos eletrônicos, internacionais e relações sujeitas a lei especial podem exigir coordenação com normas próprias.", "Lugar da celebração", "local juridicamente atribuído à formação do contrato"),
    "436": row("Quem estipula obrigação em benefício de terceiro pode exigir seu cumprimento. O beneficiário também pode cobrar se aderir ao contrato, ficando sujeito às condições pactuadas enquanto o estipulante puder mantê-las sem inovação nos termos legais.", "O contrato cria vantagem para pessoa que não participou originalmente. Estipulante e terceiro podem ter legitimidade para exigir, dentro dos limites do ajuste.", "Empresa contrata seguro em favor de empregado; tanto o estipulante quanto o beneficiário podem exigir a prestação conforme o contrato.", "O terceiro não recebe mais direitos que os previstos e sua posição depende de anuência e das faculdades reservadas ao estipulante.", "Estipulação em favor de terceiro", "contrato em que uma parte obtém prestação destinada a beneficiar pessoa externa ao ajuste inicial"),
    "437": row("Quando o contrato dá ao terceiro beneficiário o direito de exigir a prestação, o estipulante não pode liberar o devedor.", "A atribuição direta do direito consolida a proteção do terceiro e impede que o estipulante desfaça unilateralmente a obrigação em prejuízo dele.", "Contrato permite ao beneficiário cobrar pensão; o estipulante não pode depois perdoar o devedor dessa prestação.", "A regra depende de o direito de reclamar execução ter sido efetivamente atribuído ao terceiro.", "Exoneração do devedor", "liberação da obrigação que antes vinculava o responsável pela prestação"),
    "438": row("O estipulante pode reservar no contrato a faculdade de trocar o terceiro beneficiário sem consentimento dele nem do outro contratante. A substituição pode ocorrer por ato em vida ou por disposição de última vontade.", "A troca unilateral só existe quando foi previamente reservada. Ela permite adaptar o beneficiário sem refazer o contrato.", "Contratante reserva o direito de substituir o beneficiário de prestação por documento posterior ou testamento.", "Sem reserva, não se presume poder irrestrito de substituição. Devem ser observadas forma e regras sucessórias pertinentes.", "Disposição de última vontade", "ato destinado a produzir efeitos após a morte, como o testamento"),
    "439": row("Quem promete que terceiro praticará determinado ato responde por perdas e danos se ele não o fizer. A responsabilidade é afastada quando o terceiro é cônjuge do promitente, o ato depende de sua anuência e, pelo regime de bens, a indenização atingiria seu patrimônio.", "O promitente garante a obtenção do fato alheio e assume o risco da recusa, sem transformar o terceiro em obrigado.", "Sócio promete obter assinatura de outro e indeniza o contratante se não consegue.", "A exceção conjugal exige cumulativamente anuência necessária e impacto patrimonial decorrente do regime matrimonial.", "Promessa de fato de terceiro", "compromisso de conseguir comportamento de pessoa que não assumiu diretamente a obrigação"),
    "440": row("Se o terceiro posteriormente assume a obrigação, quem antes prometeu por ele não responde pela falta de cumprimento desse terceiro.", "A adesão do terceiro desloca para ele a responsabilidade pela prestação assumida. O promitente inicial garantia a obtenção do compromisso, não necessariamente sua execução posterior.", "Pessoa prometida assina o acordo e depois inadimple; a cobrança se dirige a ela, não ao intermediário, por esta regra.", "Garantia adicional do promitente pode produzir resultado diferente se estiver expressamente pactuada.", "Obrigar-se", "assumir diretamente dever jurídico de realizar a prestação"),
    "441": row("Em contrato comutativo, o adquirente pode rejeitar coisa com defeito oculto existente que a torne inadequada ao uso ou reduza seu valor. A regra também alcança doação com encargo.", "Vício redibitório rompe a equivalência esperada porque não era perceptível e compromete utilidade ou valor do bem.", "Comprador descobre defeito interno preexistente que impede o funcionamento regular da máquina e pede desfazimento.", "Desgaste aparente, defeito superveniente ou problema irrelevante não satisfazem automaticamente os requisitos. Prazos dos arts. 445 e 446 devem ser observados.", "Vício redibitório", "defeito oculto preexistente que reduz valor ou torna a coisa imprópria ao uso"),
    "442": row("Em vez de desfazer o contrato por vício oculto, o adquirente pode conservar a coisa e pedir redução do preço.", "A ação estimatória oferece alternativa proporcional quando o bem ainda é útil apesar do defeito. A escolha pertence ao adquirente dentro do regime legal.", "Veículo tem defeito oculto reparável; comprador fica com ele e pede abatimento compatível com a desvalorização.", "Não se acumulam redibição e abatimento como remédios principais. Danos adicionais dependem de requisitos próprios.", "Ação estimatória", "pedido de redução do preço em razão de vício oculto"),
    "443": row("Se o alienante conhecia o defeito oculto, devolve o que recebeu e indeniza perdas e danos. Se o ignorava, restitui o valor recebido e as despesas do contrato.", "A ciência do vendedor agrava sua responsabilidade. Mesmo sem conhecimento, permanece a obrigação restitutória ligada à redibição.", "Vendedor sabia do defeito estrutural e o omitiu; devolve o preço e indeniza prejuízos comprovados.", "O regime pressupõe vício redibitório e desfazimento. A prova do conhecimento é relevante para perdas e danos.", "Alienante", "pessoa que transfere a coisa por contrato"),
    "444": row("A responsabilidade por vício oculto continua quando a coisa perece em poder do adquirente por causa de defeito que já existia na entrega.", "O desaparecimento do bem não transfere ao adquirente o risco de um vício originário que provocou a perda.", "Animal adquirido morre por doença oculta preexistente; o alienante continua sujeito ao regime de vícios.", "É necessário provar que o perecimento decorreu do defeito anterior, e não de conduta do adquirente ou evento independente.", "Tradição", "entrega da coisa ao adquirente"),
    "445": row("O direito à redibição ou abatimento decai em trinta dias para móvel e um ano para imóvel, em regra desde a entrega; se o adquirente já tinha a posse, conta-se da alienação pela metade. Vício de descoberta tardia conta da ciência, limitado a cento e oitenta dias para móvel e um ano para imóvel. Animais seguem lei especial ou usos locais.", "São prazos decadenciais específicos e variam conforme bem, posse e possibilidade de descoberta.", "Defeito interno de máquina só aparece depois; o prazo começa quando conhecido, respeitado o limite máximo legal.", "A contagem exige classificar o bem e a natureza do vício. Garantia contratual pode suspender o curso nos termos do art. 446.", "Redibição", "desfazimento do contrato por vício oculto relevante"),
    "446": row("Durante cláusula de garantia, os prazos do artigo anterior não correm. Descoberto o defeito, porém, o adquirente deve comunicá-lo ao alienante em até trinta dias, sob pena de perder o direito.", "A garantia posterga a decadência principal, mas cria dever de denúncia rápida para permitir verificação e solução do problema.", "Comprador encontra falha durante garantia e informa o vendedor dentro de trinta dias.", "Garantia não autoriza inércia. O prazo de comunicação conta da descoberta e precisa ser comprovável.", "Denúncia do defeito", "comunicação ao alienante de que foi identificado vício na coisa"),
    "447": row("Nos contratos onerosos, quem transfere o bem responde pela evicção, inclusive quando a aquisição ocorreu em hasta pública.", "Evicção protege o adquirente que perde total ou parcialmente a coisa porque terceiro possuía direito anterior juridicamente reconhecido.", "Comprador perde imóvel para verdadeiro proprietário e cobra do alienante as consequências legais.", "A garantia não se confunde com vício físico. Trata-se de defeito jurídico do direito transmitido e pode ser modulada nos artigos seguintes.", "Evicção", "perda da coisa adquirida em razão de direito anterior de terceiro"),
    "448": row("As partes podem, por cláusula expressa, aumentar, reduzir ou excluir a responsabilidade do alienante pela evicção.", "A garantia admite modulação contratual, mas a exclusão não elimina necessariamente toda restituição, conforme o conhecimento e a assunção do risco pelo adquirente.", "Contrato amplia a garantia para cobrir despesas adicionais caso o bem seja perdido por direito anterior.", "A cláusula deve ser expressa e deve ser lida junto ao art. 449. Leis especiais podem restringir a autonomia.", "Cláusula de evicção", "pacto que disciplina a extensão da garantia contra perda jurídica do bem"),
    "449": row("Mesmo existindo cláusula de exclusão, o adquirente evicto recupera o preço se desconhecia o risco ou, informado, não o assumiu.", "Para perder também a restituição do preço, não basta exclusão genérica: o adquirente precisa conhecer o risco específico e aceitá-lo.", "Comprador não foi avisado de disputa sobre o imóvel; apesar da cláusula excludente, recebe de volta o preço após perdê-lo.", "Conhecimento e assunção são requisitos distintos. A prova da informação não demonstra automaticamente aceitação do risco.", "Assunção do risco", "aceitação consciente de suportar determinada possibilidade de perda"),
    "450": row("Salvo pacto diferente, o evicto recebe integralmente o preço e também indenização por frutos restituídos, despesas contratuais, danos diretos, custas e honorários do advogado contratado. O preço é calculado pelo valor da coisa no momento da evicção e, se parcial, proporcionalmente à perda.", "A reparação busca recompor aquisição frustrada e despesas diretamente ligadas à perda jurídica.", "Comprador perde metade do terreno e recebe parcela do valor atual, além de despesas cabíveis.", "A extensão pode ser ajustada dentro dos limites legais. Cada parcela exige vínculo com a evicção e não admite duplicidade.", "Evicto", "adquirente que sofre perda total ou parcial da coisa por direito de terceiro"),
    "451": row("O alienante continua responsável mesmo se a coisa estiver deteriorada, salvo quando a deterioração decorreu de dolo do adquirente.", "Desgaste ou dano não elimina a garantia de evicção. A exceção impede que o adquirente agrave intencionalmente o bem e transfira esse custo ao alienante.", "Bem sofre desgaste normal antes de ser perdido para terceiro; a responsabilidade pela evicção permanece.", "A exclusão exige dolo do adquirente relacionado à deterioração, não simples uso ou culpa automaticamente.", "Deterioração", "redução da integridade, utilidade ou valor da coisa"),
    "452": row("Se o adquirente obteve vantagem econômica com a deterioração e não foi obrigado a indenizá-la, essa vantagem é abatida do valor devido pelo alienante.", "A dedução evita que o evicto receba reparação integral e conserve benefício derivado da perda física do bem.", "Adquirente vende peças retiradas da máquina antes da evicção; o valor não indenizado é descontado da restituição.", "Só se deduz vantagem efetivamente obtida e não compensada por condenação anterior.", "Auferir vantagem", "obter benefício econômico ou patrimonial"),
    "453": row("Benfeitorias necessárias ou úteis que não foram pagas ao evicto devem ser indenizadas pelo alienante.", "A garantia cobre investimentos relevantes que o adquirente perdeu com a evicção e não recuperou do terceiro vencedor.", "Comprador fez reparo estrutural indispensável e não recebeu reembolso na ação do verdadeiro dono; cobra do vendedor.", "Benfeitorias voluptuárias não entram nesta regra. É preciso comprovar natureza, valor e ausência de pagamento anterior.", "Benfeitoria necessária", "obra indispensável à conservação da coisa"),
    "454": row("Se benfeitorias pagas ao evicto foram realizadas pelo próprio alienante, seu valor é considerado no cálculo da restituição.", "A regra evita que o adquirente receba duas vezes valor ligado à mesma melhoria e ajusta as contas entre as partes.", "Vendedor havia construído melhoria depois indenizada pelo terceiro ao comprador; esse montante entra no acerto da evicção.", "O cálculo depende de identificar quem realizou a obra e qual valor já foi efetivamente abonado.", "Abono de benfeitorias", "pagamento destinado a compensar melhorias incorporadas ao bem"),
    "455": row("Se a evicção parcial for relevante, o adquirente escolhe entre desfazer o contrato e receber a parte do preço correspondente à perda. Se for pequena, cabe apenas indenização.", "A gravidade do desfalque determina o remédio. Perda que compromete substancialmente o negócio permite resolução; perda menor mantém o contrato com compensação.", "Comprador perde área essencial do imóvel e opta por resolver a compra.", "A considerabilidade é avaliada no caso concreto, considerando finalidade, proporção e utilidade restante.", "Desfalque", "redução patrimonial causada pela perda parcial da coisa"),
    "457": row("O adquirente não pode exigir garantia por evicção se sabia que a coisa pertencia a terceiro ou era litigiosa.", "Quem contrata conhecendo o defeito jurídico assume o risco indicado e não recebe a proteção ordinária contra evicção.", "Comprador sabe que o imóvel é de terceiro e, mesmo assim, aceita adquiri-lo; depois não cobra evicção por esse fato.", "A ciência deve ser comprovada e específica. A simples existência de dúvida não equivale necessariamente a conhecimento pleno.", "Coisa litigiosa", "bem cujo domínio ou posse é objeto de disputa jurídica conhecida"),
    "458": row("No contrato aleatório sobre coisa ou fato futuro, se uma parte assume o risco de nada vir a existir, a outra conserva direito a toda a contraprestação, desde que não tenha agido com dolo ou culpa.", "Trata-se da compra de esperança: o risco de inexistência integra o objeto econômico do negócio.", "Comprador adquire por preço fixo toda a pesca futura e assume o risco de o barco não capturar nada.", "Dolo ou culpa de quem deveria proporcionar o resultado afasta a proteção. A assunção do risco deve resultar do contrato.", "Compra da esperança", "contrato em que o adquirente assume inclusive o risco de inexistência total do resultado futuro"),
    "459": row("Se o adquirente assume apenas o risco da quantidade de coisa futura, o alienante recebe o preço integral ainda que a quantidade seja menor, desde que não tenha culpa. Se nada existir, não há alienação e o preço deve ser devolvido.", "Aqui se compra a coisa futura esperada, variando sua quantidade, mas não se assume inexistência total.", "Comprador paga por colheita futura e recebe produção pequena; mantém o preço. Se nenhuma unidade nasce, recupera o pagamento.", "Distingue-se do art. 458 pelo alcance do risco. Culpa do alienante também impede que ele se beneficie da frustração.", "Compra da coisa esperada", "contrato aleatório em que se assume variação de quantidade, mas não inexistência total"),
    "460": row("Em contrato aleatório sobre coisa já existente, mas submetida a risco assumido pelo adquirente, o alienante mantém direito ao preço mesmo que, na data do contrato, ela já tenha perecido parcial ou totalmente.", "A negociação recai sobre a incerteza conscientemente assumida quanto ao estado ou sobrevivência do bem existente.", "Comprador adquire carga em viagem por sua conta e risco e paga mesmo descobrindo que ela já havia perecido.", "A regra deve ser lida com o artigo seguinte, que trata da anulação quando apenas o alienante sabia que o risco já se consumara.", "Risco assumido", "possibilidade de perda incorporada conscientemente ao equilíbrio do contrato"),
}
